$aaSource=static function(array $source)use($aat,$aav):void{
 $catalog=$source['catalog'];$contact=$source['contact'];$labels=['name'=>'Bezeichnung','description'=>'Beschreibung','amount'=>'Betrag / Einzelpreis brutto (EUR)','interval'=>'Zeitraum','billing'=>'Abrechnungszeitraum','tax_rate'=>'MwSt.','sphere'=>'Sphäre','tax_account'=>'Steuerkonto','tags'=>'Tags (durch Komma getrennt)','purpose'=>'Verwendungszweck / Rechnungsposition','pricing'=>'Betragsart','active'=>'Aktiv'];
