 ?><h4><?= e($aat('Gewählter Kontakt')) ?></h4><dl class="general-settings-description"><?php foreach(['id'=>'Kontaktkennung','name'=>'Name','email'=>'E-Mail','version'=>'Gespeicherte Fassung']as$key=>$label):?><dt><?= e($aat($label)) ?></dt><dd><?= e($aav($contact[$key])) ?></dd><?php endforeach ?></dl><details class="general-settings-values" data-assignment-source-values><summary><?= e($aat('Vollständige Tarifquelle')) ?></summary><p><?= e($catalog['id']) ?> · <?= e($aat('Gespeicherte Fassung')) ?> <?= e($catalog['version']) ?></p><dl class="general-settings-description"><?php foreach($labels as$key=>$label):$value=$catalog['data'][$key]??'';?><dt><?= e($aat($label)) ?></dt><dd><?= e($key==='active'?$aat($value?'Aktiv':'Inaktiv'):(isset($enums[$key][$aav($value)])?$aat($enums[$key][$aav($value)]):$aav($value))) ?></dd><?php endforeach ?></dl><?php foreach($catalog['data']['tiers']??[]as$row):?><dl class="general-settings-description"><dt><?= e($aat('Ab Jahren')) ?></dt><dd><?= e($aav($row['from'])) ?></dd><dt><?= e($aat('Betrag brutto (EUR)')) ?></dt><dd><?= e($aav($row['amount'])) ?></dd></dl><?php endforeach ?></details><?php if($source['linked_membership_tariff']):?><p><?= e($aat('Verknüpfter Einzel- oder Familienjahresbeitrag. Die verbindliche Beitragsforderung bleibt ein eigener Vorgang.')) ?></p><?php endif;
