$aaSourceFull=static function(array $source)use($aat,$aaSource):void{?><h4><?= e($aat('Zugehörige Zuweisung')) ?></h4><dl class="general-settings-description"><?php foreach(['id'=>'Zuweisungskennung','version'=>'Gespeicherte Fassung']as$key=>$label):?><dt><?= e($aat($label)) ?></dt><dd><?= e($source['assignment'][$key]) ?></dd><?php endforeach;foreach(['start'=>'Beginn','end'=>'Ende']as$key=>$label):?><dt><?= e($aat($label)) ?></dt><dd><?= e($source['assignment']['data'][$key]===''?$aat('Offen'):$source['assignment']['data'][$key]) ?></dd><?php endforeach ?></dl><?php $aaSource($source); };

$aaPlan=static function(?array $plan)use($aat,$aaData):void{if(!$plan){?><p><?= e($aat('Es ist noch keine Automatik eingerichtet.')) ?></p><?php return;}?><dl class="general-settings-description"><dt><?= e($aat('Gespeicherte Fassung')) ?></dt><dd data-automation-current-version><?= e($plan['version']) ?></dd><dt><?= e($aat('Status')) ?></dt><dd data-automation-status><?= e($aat($plan['status']==='active'?'Aktiv':'Pausiert')) ?></dd><dt><?= e($aat('Monate je Abrechnung')) ?></dt><dd><?= e($plan['interval_months']) ?></dd><dt><?= e($aat('Tag im Monat, spätestens Monatsende')) ?></dt><dd><?= e($plan['schedule_day']) ?></dd></dl><?php $aaData(['first'=>$plan['next_on'],'mode'=>$plan['mode'],'due_days'=>$plan['due_days']]);if($plan['reason']==='review'):?><p role="status"><?= e($aat('Preisgrundlage oder Freigabe prüfen')) ?></p><?php endif;$approved=json_decode($plan['approved_quote'],true,64,JSON_THROW_ON_ERROR);?><details class="general-settings-values"><summary><?= e($aat('Damals freigegebene Preisgrundlage')) ?></summary><p><?= e($approved['contact_name']) ?> · <?= e($approved['name']) ?></p><p><strong><?= e(\Kulturhus\Verein\Finance::decimal($approved['amount_cents'])) ?> EUR</strong></p><p><?= e($approved['period_start']) ?> – <?= e($approved['period_end']) ?></p><p><?= e($aat('Freigegeben durch')) ?>: <?= e($plan['approved_by']) ?></p><p><code><?= e($plan['source_hash']) ?></code></p></details><?php };
$aaReview=static function(array $review)use($aat,$aaData,$aaPlan,$aaSourceFull):void{?><p><?= e($aat($review['input']['operation']==='activate'?'Automatik freigeben':'Automatik pausieren')) ?></p><?php $aaData($review['input']['data']);?><details class="general-settings-values"><summary><?= e($aat('Vollständige geprüfte Automatikquelle')) ?></summary><?php $aaSourceFull($review['source']);$price=$review['source']['personal_price'];?><p><?= e($aat('Aktueller gespeicherter persönlicher Preis')) ?> · <?= e($aat('Gespeicherte Fassung')) ?> <?= e($price['version']) ?> · <?= e($aat(['none'=>'Tarifpreis','fixed'=>'Persönlicher Festpreis','percent'=>'Prozent-Rabatt'][$price['data']['mode']])) ?><?php if($price['data']['mode']!=='none'):?> · <?= e(\Kulturhus\Verein\Finance::decimal($price['data']['value_units'])) ?><?php endif ?></p><?php if($review['source']['tax_account']):?><p><?= e($aat('Steuerkonto')) ?>: <?= e($review['source']['tax_account']['code']) ?> · <?= e($review['source']['tax_account']['name']) ?></p><?php endif ?></details><details class="general-settings-values"><summary><?= e($aat('Damals gelesener vollständiger Automatikstand')) ?></summary><?php $aaPlan($review['current']['canonical']);?></details><?php if($review['quote']):$quote=$review['quote'];?><article class="general-settings-row" data-automation-reviewed-price><h4><?= e($quote['contact_name']) ?></h4><p><?= e($quote['name']) ?></p><p><strong data-automation-reviewed-amount><?= e(\Kulturhus\Verein\Finance::decimal($quote['amount_cents'])) ?> EUR</strong></p><p><?= e($quote['period_start']) ?> – <?= e($quote['period_end']) ?></p><?php if($quote['charge']):?><p><?= e($aat('Der erste Zeitraum hat bereits einen Beleg. Der getrennte Lauf verwendet ihn ohne zweite Anlage.')) ?></p><a class="btn btn-outline theme-secondary" data-navigation-native href="<?= e(url(['view'=>'finance','tab'=>'receipts','entry'=>$quote['charge']['entry_id']])) ?>"><?= e($aat('Vorhandenen Beleg öffnen')) ?></a><?php endif ?></article><?php endif;if($review['existing_run']):$earlier=$review['existing_run'];?><article class="general-settings-row" data-automation-existing-run><p><?= e($aat('Für diesen ersten Tag ist bereits ein tatsächlicher Lauf gespeichert. Der getrennte Lauf erhält dieses Original und geht ohne zweite Anlage zum nächsten freigegebenen Termin weiter.')) ?></p><p><?= e($earlier['scheduled_on']) ?> · <?= e(\Kulturhus\Verein\Finance::decimal($earlier['quote']['amount_cents'])) ?> EUR</p><a class="btn btn-outline theme-secondary" data-navigation-native href="<?= e(url(['view'=>'finance','tab'=>'receipts','entry'=>$earlier['entry_id']])) ?>"><?= e($aat('Vorhandenen Beleg öffnen')) ?></a></article><?php endif;};
